'use client';

import {
  AnimatePresence,
  LayoutGroup,
  motion,
  useReducedMotion,
} from 'motion/react';
import { useId, useState } from 'react';

import { formatTokens } from '@/registry/ndeko/lib/agent-run';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';

import { CompactOffer, contextAnnouncementOf } from './_parts/compact-offer';
import {
  freeTokensOf,
  LEVEL_WORD,
  levelOf,
  PART_FILL,
  percentOf,
  RESERVE_STYLE,
  TURNS,
  type Compaction,
  type ContextBudget,
  type ContextPartId,
} from './_parts/context';
import { ContextHeader } from './_parts/context-header';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import {
  FADE,
  risePresenceOf,
  springOf,
} from '@/registry/ndeko/lib/motion-presets';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';
import {
  squarify,
  type TreemapEntry,
  type TreemapRect,
} from './_parts/treemap';
import {
  useContextControls,
  useContextRun,
  type CompactStatus,
} from './_parts/use-context-demo';

type TileKind = ContextPartId | 'free' | 'reserve';

type Tile = {
  id: string;
  layoutId: string;
  kind: TileKind;
  group: string;
  label: string;
  tokens: number;
  rect: TreemapRect;
};

type View = 'before' | 'after';

/** The map is laid out on a 4 by 3 field, the shape of its frame. */
const FIELD_WIDTH = 100;

const FIELD_HEIGHT = 75;

const FIELD: TreemapRect = {
  x: 0,
  y: 0,
  width: FIELD_WIDTH,
  height: FIELD_HEIGHT,
};

/** The summary takes the place of the oldest turn, so that turn is the one that turns into it. */
const SUMMARY_LAYOUT_ID = TURNS[0].id;

const VIEWS: Segment<View>[] = [
  { value: 'before', label: 'Before' },
  { value: 'after', label: 'After' },
];

const GROUP_LABEL: Record<TileKind, string> = {
  system: 'System',
  tools: 'Tools',
  files: 'Files',
  summary: 'Summary',
  conversation: 'Conversation',
  free: 'Free',
  reserve: 'Held for the answer',
};

function layoutIdOf(itemId: string) {
  if (itemId === 'summary') {
    return SUMMARY_LAYOUT_ID;
  }
  return itemId;
}

function groupEntriesOf(budget: ContextBudget) {
  const free = freeTokensOf(budget);
  const entries: TreemapEntry[] = budget.parts.map((part) => ({
    id: part.id,
    value: part.tokens,
  }));
  entries.push({ id: 'free', value: free });
  entries.push({ id: 'reserve', value: budget.reserve });
  return entries;
}

function singleTile(
  kind: 'free' | 'reserve',
  tokens: number,
  rect: TreemapRect
): Tile {
  const label = GROUP_LABEL[kind];
  return { id: kind, layoutId: kind, kind, group: label, label, tokens, rect };
}

function tilesOf(budget: ContextBudget) {
  const groups = squarify(groupEntriesOf(budget), FIELD);
  const tiles: Tile[] = [];
  for (const group of groups) {
    if (group.id === 'free') {
      tiles.push(singleTile('free', group.value, group.rect));
      continue;
    }
    if (group.id === 'reserve') {
      tiles.push(singleTile('reserve', group.value, group.rect));
      continue;
    }
    const part = budget.parts.find((candidate) => candidate.id === group.id);
    if (!part) {
      continue;
    }
    const items = part.items.map((item) => ({
      id: item.id,
      value: item.tokens,
    }));
    const placedItems = squarify(items, group.rect);
    for (const placed of placedItems) {
      const item = part.items.find((candidate) => candidate.id === placed.id);
      tiles.push({
        id: placed.id,
        layoutId: layoutIdOf(placed.id),
        kind: part.id,
        group: part.label,
        label: item?.label ?? placed.id,
        tokens: placed.value,
        rect: placed.rect,
      });
    }
  }
  return tiles;
}

function rectStyleOf(rect: TreemapRect): React.CSSProperties {
  const left = (rect.x / FIELD_WIDTH) * 100;
  const top = (rect.y / FIELD_HEIGHT) * 100;
  const width = (rect.width / FIELD_WIDTH) * 100;
  const height = (rect.height / FIELD_HEIGHT) * 100;
  return {
    left: `${left}%`,
    top: `${top}%`,
    width: `${width}%`,
    height: `${height}%`,
  };
}

function tileFillOf(kind: TileKind): React.CSSProperties {
  if (kind === 'reserve') {
    return RESERVE_STYLE;
  }
  if (kind === 'free') {
    return {};
  }
  const fill = PART_FILL[kind];
  return {
    backgroundColor: `color-mix(in oklab, ${fill} 24%, var(--card))`,
    boxShadow: `inset 0 0 0 var(--hairline) color-mix(in oklab, ${fill} 40%, transparent)`,
  };
}

type TileRoom = 'none' | 'name' | 'full';

function roomOf(rect: TreemapRect): TileRoom {
  const isWideEnough = rect.width >= 20;
  const isTallEnough = rect.height >= 13;
  if (isWideEnough && isTallEnough) {
    return 'full';
  }
  const fitsName = rect.width >= 17;
  const fitsLine = rect.height >= 8;
  if (fitsName && fitsLine) {
    return 'name';
  }
  return 'none';
}

function selectionRingOf(isSelected: boolean) {
  if (isSelected) {
    return 'ring-2 ring-foreground/60 ring-inset';
  }
  return 'ring-0';
}

function tileShapeOf(kind: TileKind) {
  if (kind === 'free') {
    return 'hairline-border border-dashed border-foreground/25 text-muted-foreground';
  }
  return 'text-foreground';
}

type TileButtonProps = {
  tile: Tile;
  isSelected: boolean;
  onSelect: (tileId: string) => void;
};

function TileButton({ tile, isSelected, onSelect }: TileButtonProps) {
  const room = roomOf(tile.rect);
  const showsName = room !== 'none';
  const showsTokens = room === 'full';
  const tokens = formatTokens(tile.tokens);

  return (
    <button
      type='button'
      aria-pressed={isSelected}
      aria-label={`${tile.label}, ${tile.group}, ${tokens} tokens`}
      onClick={() => onSelect(tile.id)}
      className={cn(
        'focus-visible:ring-ring/40 flex size-full cursor-pointer flex-col items-start justify-start overflow-hidden rounded-md p-1.5 text-start transition-[box-shadow] duration-150 outline-none focus-visible:ring-[3px]',
        tileShapeOf(tile.kind),
        selectionRingOf(isSelected)
      )}
      style={tileFillOf(tile.kind)}
    >
      {showsName && (
        <motion.span
          layout='position'
          className='w-full truncate text-[11px] leading-4 font-medium'
        >
          {tile.label}
        </motion.span>
      )}
      {showsTokens && (
        <motion.span
          layout='position'
          className='text-muted-foreground text-[11px] leading-4 tabular-nums'
        >
          {tokens}
        </motion.span>
      )}
    </button>
  );
}

function TileDetails({
  tile,
  budget,
}: {
  tile: Tile | undefined;
  budget: ContextBudget;
}) {
  if (!tile) {
    return (
      <p className='text-muted-foreground text-xs leading-5'>
        Select a tile to see what it holds
      </p>
    );
  }
  const share = percentOf(tile.tokens, budget);
  const shareText = `${share.toFixed(1)}%`;

  return (
    <dl className='grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-xs'>
      <dt className='text-muted-foreground'>Holds</dt>
      <dd className='truncate font-medium'>{tile.label}</dd>
      <dt className='text-muted-foreground'>Part</dt>
      <dd>{tile.group}</dd>
      <dt className='text-muted-foreground'>Tokens</dt>
      <dd className='tabular-nums'>
        {formatTokens(tile.tokens)}, {shareText} of the window
      </dd>
    </dl>
  );
}

function viewedBudgetOf(
  view: View,
  budget: ContextBudget,
  budgetBefore: ContextBudget
) {
  if (view === 'before') {
    return budgetBefore;
  }
  return budget;
}

export type ContextTreemapProps = {
  budget: ContextBudget;
  /** The same context without the last compaction, for the Before view. */
  budgetBefore?: ContextBudget;
  compaction?: Compaction | null;
  canCompact?: boolean;
  compactStatus?: CompactStatus;
  onCompact?: () => void;
  className?: string;
};

export function ContextTreemap({
  budget,
  budgetBefore = budget,
  compaction = null,
  canCompact = false,
  compactStatus = 'idle',
  onCompact,
  className,
}: ContextTreemapProps) {
  const [view, setView] = useState<View>('after');
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const titleId = useId();
  const layoutGroupId = useId();
  const shouldReduceMotion = useReducedMotion();
  const spring = springOf(shouldReduceMotion);
  const risePresence = risePresenceOf(shouldReduceMotion);
  const hasCompaction = compaction !== null;
  const shownView = shownViewOf(view, hasCompaction);
  const shownBudget = viewedBudgetOf(shownView, budget, budgetBefore);
  const tiles = tilesOf(shownBudget);
  const selectedTile = tiles.find((tile) => tile.id === selectedId);

  function select(tileId: string) {
    setSelectedId((current) => {
      if (current === tileId) {
        return null;
      }
      return tileId;
    });
  }

  return (
    <section
      aria-labelledby={titleId}
      className={cn(
        'bg-card hairline-ring ring-border flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <ContextHeader budget={shownBudget} titleId={titleId} />
      <AnimatePresence initial={false}>
        {hasCompaction && (
          <motion.div key='views' className='flex' {...risePresence}>
            <Segments
              value={shownView}
              segments={VIEWS}
              onValueChange={setView}
              label='Compare the context before and after the compaction'
            />
          </motion.div>
        )}
      </AnimatePresence>
      <LayoutGroup id={layoutGroupId}>
        <ul
          aria-label='Tiles of the context, sized by tokens'
          className='relative aspect-[4/3] w-full'
        >
          <AnimatePresence initial={false}>
            {tiles.map((tile) => (
              <motion.li
                key={tile.id}
                layoutId={tile.layoutId}
                layout
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ layout: spring, opacity: FADE }}
                className='absolute p-px'
                style={rectStyleOf(tile.rect)}
              >
                <TileButton
                  tile={tile}
                  isSelected={tile.id === selectedId}
                  onSelect={select}
                />
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      </LayoutGroup>
      <AnimatedSize>
        <TileDetails tile={selectedTile} budget={shownBudget} />
      </AnimatedSize>
      <CompactOffer
        budget={budget}
        canCompact={canCompact}
        compactStatus={compactStatus}
        compaction={compaction}
        onCompact={onCompact}
      />
    </section>
  );
}

function shownViewOf(view: View, hasCompaction: boolean): View {
  if (hasCompaction) {
    return view;
  }
  return 'after';
}

export default function Run08() {
  const { ref, turns, restart, isFinished } = useContextRun();
  const controls = useContextControls(turns);
  const level = levelOf(controls.budget);
  const announcement = contextAnnouncementOf(
    level,
    LEVEL_WORD[level],
    controls.compaction
  );

  function replay() {
    controls.reset();
    restart();
  }

  return (
    <div ref={ref} className='flex w-full max-w-[30rem] flex-col gap-2'>
      <ContextTreemap
        budget={controls.budget}
        budgetBefore={controls.budgetBefore}
        compaction={controls.compaction}
        canCompact={controls.canCompact}
        compactStatus={controls.compactStatus}
        onCompact={controls.compact}
      />
      <div className='flex h-7 items-center justify-end'>
        <ReplayButton
          isShown={isFinished}
          onReplay={replay}
          label='Replay the conversation'
        />
      </div>
      <LiveRegion message={announcement} />
    </div>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';

import { formatTokens } from '@/registry/ndeko/lib/agent-run';
import { CheckIcon } from '@/registry/ndeko/lib/icons';

import {
  compactionLineOf,
  freeTokensOf,
  levelOf,
  type Compaction,
  type ContextBudget,
  type ContextLevel,
} from './context';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { risePresenceOf } from '@/registry/ndeko/lib/motion-presets';
import type { CompactStatus } from './use-context-demo';

const COMPACT_LABELS: Record<MorphState, string> = {
  idle: 'Compact',
  busy: 'Compacting',
  done: 'Compacted',
};

function morphStateOf(status: CompactStatus): MorphState {
  if (status === 'compacting') {
    return 'busy';
  }
  return 'idle';
}

function isOfferShown(
  level: ContextLevel,
  canCompact: boolean,
  status: CompactStatus
) {
  const isCompactSoon = level === 'compact';
  const isCompacting = status === 'compacting';
  const isAvailable = canCompact || isCompacting;
  return isCompactSoon && isAvailable;
}

function traceOf(compaction: Compaction | null, isOffered: boolean) {
  if (isOffered) {
    return null;
  }
  return compaction;
}

type CompactOfferProps = {
  budget: ContextBudget;
  canCompact: boolean;
  compactStatus: CompactStatus;
  compaction: Compaction | null;
  onCompact?: () => void;
};

export function CompactOffer({
  budget,
  canCompact,
  compactStatus,
  compaction,
  onCompact,
}: CompactOfferProps) {
  const shouldReduceMotion = useReducedMotion();
  const risePresence = risePresenceOf(shouldReduceMotion);
  const level = levelOf(budget);
  const free = freeTokensOf(budget);
  const freeText = formatTokens(free);
  const isOffered = isOfferShown(level, canCompact, compactStatus);
  const trace = traceOf(compaction, isOffered);

  return (
    <AnimatePresence initial={false} mode='popLayout'>
      {isOffered && (
        <motion.div key='offer' className='@container' {...risePresence}>
          <div className='bg-warning/10 flex flex-col gap-2.5 rounded-lg p-3 @lg:flex-row @lg:items-center'>
            <p className='text-warning-foreground min-w-0 flex-1 text-xs leading-5'>
              {freeText} tokens left before the reserve. Fold the older turns
              into a summary to keep going.
            </p>
            <MorphButton
              type='button'
              size='sm'
              state={morphStateOf(compactStatus)}
              labels={COMPACT_LABELS}
              onClick={onCompact}
            />
          </div>
        </motion.div>
      )}
      {trace && (
        <motion.p
          key='trace'
          className='text-muted-foreground flex items-center gap-2 text-xs'
          {...risePresence}
        >
          <CheckIcon className='text-success-foreground size-3.5' />
          {compactionLineOf(trace)}
        </motion.p>
      )}
    </AnimatePresence>
  );
}

export function contextAnnouncementOf(
  level: ContextLevel,
  levelWord: string,
  compaction: Compaction | null
) {
  if (compaction) {
    const line = compactionLineOf(compaction);
    return `${line}. Context: ${levelWord}`;
  }
  if (level === 'compact') {
    return `Context: ${levelWord}. Compact is available`;
  }
  return `Context: ${levelWord}`;
}

'use client';

import { WordRoll } from '@/components/core/word-roll';
import { cn } from '@/registry/ndeko/lib/utils';

import {
  LEVEL_LABELS,
  LEVEL_TONE,
  LEVEL_WORD,
  levelOf,
  usedTokensOf,
  type ContextBudget,
} from './context';
import { TokenCount } from './token-count';

type ContextHeaderProps = {
  budget: ContextBudget;
  titleId: string;
  title?: string;
};

export function ContextHeader({
  budget,
  titleId,
  title = 'Context',
}: ContextHeaderProps) {
  const used = usedTokensOf(budget);
  const level = levelOf(budget);

  return (
    <header className='flex items-start justify-between gap-3'>
      <div className='min-w-0'>
        <h3 id={titleId} className='text-sm font-medium'>
          {title}
        </h3>
        <p
          className={cn(
            'text-xs transition-colors duration-200',
            LEVEL_TONE[level]
          )}
        >
          <WordRoll text={LEVEL_WORD[level]} labels={LEVEL_LABELS} />
        </p>
      </div>
      <p className='text-[13px] tabular-nums'>
        <TokenCount tokens={used} className='font-medium' />
        <span className='text-muted-foreground'>
          {' of '}
          <TokenCount tokens={budget.limit} />
        </span>
      </p>
    </header>
  );
}

import { hatchOf } from '@/registry/ndeko/lib/hatch';

export type ContextPartId =
  'system' | 'tools' | 'files' | 'summary' | 'conversation';

export type ContextItem = {
  id: string;
  label: string;
  tokens: number;
};

export type ContextPart = {
  id: ContextPartId;
  label: string;
  tokens: number;
  items: ContextItem[];
};

export type ContextBudget = {
  limit: number;
  /** Held back for the model's answer: never filled by the context. */
  reserve: number;
  parts: ContextPart[];
};

export type ContextLevel = 'room' | 'filling' | 'compact';

export type Compaction = {
  foldedTurns: number;
  summaryTokens: number;
};

export const CONTEXT_LIMIT = 200_000;

export const CONTEXT_RESERVE = 16_000;

/** Parts are parts of one whole, not entities: they take the chart ramp and a muted fill, never the series. */
export const PART_FILL: Record<ContextPartId, string> = {
  system: 'color-mix(in oklab, var(--muted-foreground) 30%, transparent)',
  tools: 'var(--chart-3)',
  files: 'var(--chart-2)',
  summary: 'var(--chart-4)',
  conversation: 'var(--chart-1)',
};

export const RESERVE_STYLE = {
  backgroundColor:
    'color-mix(in oklab, var(--muted-foreground) 8%, transparent)',
  backgroundImage: hatchOf('var(--muted-foreground)', 40),
};

export const LEVEL_WORD: Record<ContextLevel, string> = {
  room: 'Plenty of room',
  filling: 'Filling up',
  compact: 'Compact soon',
};

export const LEVEL_LABELS = [
  LEVEL_WORD.room,
  LEVEL_WORD.filling,
  LEVEL_WORD.compact,
];

export const LEVEL_TONE: Record<ContextLevel, string> = {
  room: 'text-muted-foreground',
  filling: 'text-foreground',
  compact: 'text-warning-foreground',
};

const FILLING_FROM = 0.6;

const COMPACT_FROM = 0.85;

/** The newest turns stay word for word after a compaction. */
const KEPT_TURNS = 2;

const SUMMARY_SHARE = 0.08;

export const SYSTEM_ITEMS: ContextItem[] = [
  { id: 'system-prompt', label: 'System prompt', tokens: 4_100 },
  { id: 'system-notes', label: 'Saved notes', tokens: 2_100 },
];

export const TOOL_ITEMS: ContextItem[] = [
  { id: 'tool-search', label: 'web_search results', tokens: 1_900 },
  { id: 'tool-page', label: 'fetch_page result', tokens: 2_300 },
  { id: 'tool-sheet', label: 'read_sheet rows', tokens: 2_600 },
  { id: 'tool-script', label: 'run_script output', tokens: 1_800 },
];

export const FILE_ITEMS: ContextItem[] = [
  { id: 'file-invoices', label: 'q3-invoices.xlsx', tokens: 21_400 },
  { id: 'file-contract', label: 'brightmoor-contract.pdf', tokens: 18_600 },
  { id: 'file-pricing', label: 'pricing-page.html', tokens: 9_800 },
  { id: 'file-notes', label: 'vendor-notes.md', tokens: 3_100 },
];

const TURN_TOKENS = [
  5_200, 7_400, 9_800, 6_100, 12_400, 8_300, 10_900, 7_700, 13_600, 9_200,
  11_800, 8_600,
];

function turnOf(tokens: number, index: number): ContextItem {
  const number = index + 1;
  return { id: `turn-${number}`, label: `Turn ${number}`, tokens };
}

export const TURNS: ContextItem[] = TURN_TOKENS.map(turnOf);

export function sumTokens(items: readonly { tokens: number }[]) {
  let total = 0;
  for (const item of items) {
    total += item.tokens;
  }
  return total;
}

/** What the run holds before any conversation: system, tools and every file. */
const SYSTEM_TOKENS = sumTokens(SYSTEM_ITEMS);

const TOOL_TOKENS = sumTokens(TOOL_ITEMS);

const FILE_TOKENS = sumTokens(FILE_ITEMS);

export const BASE_TOKENS = SYSTEM_TOKENS + TOOL_TOKENS + FILE_TOKENS;

export function usedTokensOf(budget: ContextBudget) {
  return sumTokens(budget.parts);
}

export function freeTokensOf(budget: ContextBudget) {
  const used = usedTokensOf(budget);
  const free = budget.limit - budget.reserve - used;
  return Math.max(0, free);
}

export function shareOf(tokens: number, budget: ContextBudget) {
  return tokens / budget.limit;
}

export function percentOf(tokens: number, budget: ContextBudget) {
  const share = shareOf(tokens, budget);
  return share * 100;
}

export function levelOf(budget: ContextBudget): ContextLevel {
  const used = usedTokensOf(budget);
  const share = shareOf(used, budget);
  if (share < FILLING_FROM) {
    return 'room';
  }
  if (share <= COMPACT_FROM) {
    return 'filling';
  }
  return 'compact';
}

export function turnsWithin(conversationTokens: number) {
  const turns: ContextItem[] = [];
  let total = 0;
  for (const turn of TURNS) {
    const next = total + turn.tokens;
    if (next > conversationTokens) {
      break;
    }
    turns.push(turn);
    total = next;
  }
  return turns;
}

export function compactionOf(turns: ContextItem[]): Compaction | null {
  const foldedTurns = turns.length - KEPT_TURNS;
  if (foldedTurns < 2) {
    return null;
  }
  const folded = turns.slice(0, foldedTurns);
  const foldedTokens = sumTokens(folded);
  const rawSummary = foldedTokens * SUMMARY_SHARE;
  const summaryHundreds = Math.round(rawSummary / 100);
  const summaryTokens = summaryHundreds * 100;
  return { foldedTurns, summaryTokens };
}

function partOf(
  id: ContextPartId,
  label: string,
  items: ContextItem[]
): ContextPart {
  return { id, label, tokens: sumTokens(items), items };
}

function turnCountOf(count: number) {
  if (count === 1) {
    return '1 turn';
  }
  return `${count} turns`;
}

type BudgetInput = {
  turns: ContextItem[];
  removedFileIds: readonly string[];
  compaction: Compaction | null;
};

export function budgetOf({
  turns,
  removedFileIds,
  compaction,
}: BudgetInput): ContextBudget {
  const files = FILE_ITEMS.filter((file) => !removedFileIds.includes(file.id));
  const foldedCount = compaction?.foldedTurns ?? 0;
  const liveTurns = turns.slice(foldedCount);
  const parts: ContextPart[] = [
    partOf('system', 'System', SYSTEM_ITEMS),
    partOf('tools', 'Tools', TOOL_ITEMS),
    partOf('files', 'Files', files),
  ];
  if (compaction) {
    const summaryLabel = `Summary of ${turnCountOf(compaction.foldedTurns)}`;
    const summary = {
      id: 'summary',
      label: summaryLabel,
      tokens: compaction.summaryTokens,
    };
    parts.push(partOf('summary', 'Summary', [summary]));
  }
  parts.push(partOf('conversation', 'Conversation', liveTurns));
  return { limit: CONTEXT_LIMIT, reserve: CONTEXT_RESERVE, parts };
}

export function compactionLineOf(compaction: Compaction) {
  const turns = turnCountOf(compaction.foldedTurns);
  const thousands = compaction.summaryTokens / 1000;
  const summary = `${thousands.toFixed(1)}k`;
  return `Folded ${turns} into a ${summary} summary`;
}

